data_s31c = FileAttachment("layers/data_s31c.json").json()

viewof slider_s31c = InputsTaux.range([0, 100000], {
  value: 20000,
  step: 20000//
  //label: "Linéaire d'itinéraires routiers interceptés en km"
})

sorted_s31c = data_s31c
  .map(d =&gt; ({ ...d, s31c: +d.s31c || 0 }))
  .filter(d =&gt; d.s31c &lt;= slider_s31c)
  .sort((a, b) =&gt; a.s31c - b.s31c)

PlotTaux.plot({
  marks: [
    PlotTaux.barY(sorted_s31c, {
      x: d =&gt; d.nom,
      y: d =&gt; d.s31c,
        fill: d =&gt; {
        const val = d.s31c;
        if (val === 0) return "#d9d9d9";
        if (val &lt; 6000) return "#edf8fb";
        if (val &lt; 26000) return "#a6bbda";
        if (val &lt; 50000) return "#896bb2";
        if (val &gt;= 50000) return "#810f7c";
        return "#67000d"; // &gt;4

      }
    }),
    PlotTaux.text(sorted_s31c, {
      x: d =&gt; d.nom,
      y: d =&gt; d.s31c,
      text: d =&gt; d.s31c.toLocaleString("fr-FR"),
      dy: -8,
      fontSize: 9,
      fill: "black",
      textAnchor: "middle"
    })
  ],
  y: {
    grid: true,
    label: "Surface des emprises des bâtiments d’habitation pouvant être inondés",
    domain: [0, Math.max(...sorted_s31c.map(d =&gt; d.s31c))],
    tickFormat: d =&gt; d.toLocaleString("fr-FR", { maximumFractionDigits: 0 })
  },
  x: {
    label: "Commune",
    tickRotate: -45,
    labelAnchor: "right"
  },
  style: {
    fontSize: "11px",
    fontFamily: "sans-serif",
    fontWeight: "bold"
  },
  width: window.innerWidth * 0.95,
  height: window.innerHeight * 0.65,
  marginBottom: 120,
  marginTop: 50,
  marginLeft: 80
})

