              ['any', ['==', ['get', layer.dynamicColor.property], null], ['==', ['get', layer.dynamicColor.property], 0]], '#d9d9d9', // null ou 0
              ['&lt;', ['get', layer.dynamicColor.property], 1000000], '#ffffff',
              ['&lt;', ['get', layer.dynamicColor.property], 5000000], '#ffaaaa',
              ['&lt;', ['get', layer.dynamicColor.property], 10000000], '#ff5555',
              ['&gt;', ['get', layer.dynamicColor.property], 10000000], '#ff0000',
              '#d9d9d9' // fallback
            ];
